SELECT *, FIRST_VALUE(status, TRUE) OVER w_part AS first_known_status, AVG(balance) OVER (PARTITION BY status ORDER BY balance, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS balance_avg_6_prior, SUM(balance) OVER w_part AS cumulative_balance, SUM(balance) OVER (ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_balance, DENSE_RANK() OVER (PARTITION BY status ORDER BY balance DESC) AS balance_dense_rank FROM accounts WINDOW w_part AS (ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
